'use strict';
const SALE_TABLES=['Parcelinha','Adesão de 1%','Adesão de 2%'];
function saleCancelledWithinEightMonths(s){if(!s?.voided||s.table===0)return false;const cancelled=s.voidedDate||s.date,start=s.date?.slice(0,7),end=cancelled?.slice(0,7);if(!/^\d{4}-\d{2}$/.test(start)||!/^\d{4}-\d{2}$/.test(end))return true;const [sy,sm]=start.split('-').map(Number),[ey,em]=end.split('-').map(Number),elapsed=(ey-sy)*12+em-sm;return elapsed>=0&&elapsed<8;}
function saleCompanyRevenue(s){if(!s)return 0;if(s.table===0){const installments=Math.min(12,Math.max(1,Number.isInteger(s.installments)?s.installments:1));return Math.round(s.amount*4*installments/1200);}if(saleCancelledWithinEightMonths(s))return Math.round(s.amount*35/1000);if(s.table===2)return Math.round(s.amount*45/1000);return Math.round(s.amount*4/100);}
function companySalesRevenue(month=$('#month').value){return (state.saleEntries||[]).filter(s=>s.date?.slice(0,7)===month).reduce((total,s)=>total+saleCompanyRevenue(s),0);}
const SALE_STEPS=['Conferir documentos e subir no Google Drive','Criar grupo no WhatsApp e enviar boas-vindas ao cliente','Enviar extrato da cota após a TED dar baixa na Embracon','Pedir ao cliente para avisar quando checar a cota e enviar no grupo da ADM para marcar como checada','Ofertar lance ao cliente'];
let saleEditing=null,salesPersonFilter='',salesSubView='list';
function saleShares(s){if(s.allocations)return s.allocations.map(a=>[a.person,a.amount]);return s.originator===s.closer?[[s.originator,s.commission]]:[[s.originator,Math.floor(s.commission/2)],[s.closer,s.commission-Math.floor(s.commission/2)]];}
function validateSales(s){const ids=new Set();for(const x of s.saleEntries||[]){if(!x||typeof x.id!=='string'||ids.has(x.id)||typeof x.client!=='string'||!x.client.trim()||!validDate(x.date)||![0,1,2].includes(x.table)||(x.installments!==undefined&&(!Number.isInteger(x.installments)||x.installments<1||x.installments>12))||![x.amount,x.commission].every(n=>Number.isSafeInteger(n)&&n>=0&&n<=100000000000)||!s.people.some(p=>p.id===x.originator)||!s.people.some(p=>p.id===x.closer)||typeof x.voided!=='boolean'||!(x.voidedDate===undefined||x.voidedDate===null||validDate(x.voidedDate)))throw Error('Venda inválida');if(x.allocations&&(!Array.isArray(x.allocations)||x.allocations.length!==(x.originator===x.closer?1:2)||x.allocations.some((a,i)=>a.person!==[x.originator,x.closer][i]||!Number.isSafeInteger(a.amount)||a.amount<0||!Number.isFinite(a.rate)||a.rate<0||a.rate>100)||x.allocations.reduce((n,a)=>n+a.amount,0)!==x.commission))throw Error('Divisão inválida');if(x.workflow!==undefined&&(!Array.isArray(x.workflow)||x.workflow.length!==SALE_STEPS.length||x.workflow.some(v=>typeof v!=='boolean')))throw Error('Etapas da venda inválidas');ids.add(x.id);}if(s.saleEntries!==undefined&&!Array.isArray(s.saleEntries))throw Error('Vendas inválidas');for(const r of Object.values(s.records)){const b=r.salesBase;if(b&&(!Array.isArray(b.sales)||b.sales.length!==3||![b.commission,...b.sales].every(n=>Number.isFinite(n)&&n>=0)||typeof b.excluded!=='boolean'))throw Error('Histórico de vendas inválido');}}
function salesRecord(key){return state.records[key]??(state.records[key]={fare:0,rides:2,days:[],paid:{},sales:[0,0,0],commission:0,commissionPaid:false});}
function normalizeParcelinhaCommissions(){if(state.parcelinhaCommissionRule==='each-participation-0.8-divided-by-12')return false;for(const s of state.saleEntries||[]){if(s.table!==0)continue;Object.assign(s,calculateSale(s.amount,0,s.originator,s.closer,0,0,s.installments||1));}state.parcelinhaCommissionRule='each-participation-0.8-divided-by-12';return true;}
function syncSales(){state.saleEntries??=[];const migrated=normalizeParcelinhaCommissions();for(const s of state.saleEntries){for(const id of new Set([s.originator,s.closer])){const r=salesRecord(s.date.slice(0,7)+':'+id);r.salesBase??={sales:[...r.sales],commission:r.commission,excluded:false};}}for(const r of Object.values(state.records)){if(r.salesBase){r.sales=r.salesBase.excluded?[0,0,0]:[...r.salesBase.sales];r.commission=r.salesBase.excluded?0:r.salesBase.commission;}}for(const s of state.saleEntries.filter(s=>!s.voided)){for(const [id,amount] of saleShares(s)){const r=salesRecord(s.date.slice(0,7)+':'+id);r.commission=(cents(r.commission)+amount)/100;r.sales[s.table]=(cents(r.sales[s.table])+s.amount)/100;}}if(migrated&&typeof window!=='undefined')setTimeout(()=>save(),0);}
function saleLocked(...entries){return entries.filter(Boolean).some(s=>[s.originator,s.closer].some(id=>{const r=state.records[s.date.slice(0,7)+':'+id];return r?.settlement||commissionPayments(r).some(p=>(p.salePayments||[]).some(x=>x.saleId===s.id));}));}
function putSale(entry){const old=(state.saleEntries||[]).find(s=>s.id===entry.id);if(saleLocked(old,entry))return false;if(old)Object.assign(old,entry);else (state.saleEntries??=[]).push({...entry});syncSales();return true;}
function salePerson(id){return state.people.find(p=>p.id===id)?.name||id;}
function monthlySales(){return (state.saleEntries||[]).filter(s=>s.date.startsWith($('#month').value));}
function saleWorkflow(s){return Array.isArray(s.workflow)&&s.workflow.length===SALE_STEPS.length?s.workflow:Array(SALE_STEPS.length).fill(false);}
function workflowDone(s){return saleWorkflow(s).filter(Boolean).length;}
function salesPendingView(entries){const active=entries.filter(s=>!s.voided),pending=active.filter(s=>workflowDone(s)<SALE_STEPS.length),complete=active.length-pending.length;return `<div class="workflow-summary"><div><small>Vendas com pendências</small><strong>${pending.length}</strong></div><div><small>Vendas concluídas</small><strong>${complete}</strong></div></div><div class="workflow-list">${active.length?active.map(s=>{const workflow=saleWorkflow(s),done=workflowDone(s);return `<article class="workflow-card ${done===SALE_STEPS.length?'complete':''}"><div class="workflow-card-head"><div><small>${esc(s.date.split('-').reverse().join('/'))} · ${SALE_TABLES[s.table]}</small><h3>${esc(s.client)}</h3><p>${esc(salePerson(s.originator))}${s.closer!==s.originator?' / '+esc(salePerson(s.closer)):''}</p></div><span>${done===SALE_STEPS.length?'Concluída':done+' de '+SALE_STEPS.length+' concluídas'}</span></div><div class="workflow-steps">${SALE_STEPS.map((label,i)=>`<button type="button" class="workflow-step ${workflow[i]?'done':''}" data-sale-step="${esc(s.id)}:${i}" aria-pressed="${workflow[i]}"><span>${workflow[i]?'✓':i+1}</span><b>${esc(label)}</b><small>${workflow[i]?'Concluída':'Marcar como concluída'}</small></button>`).join('')}</div></article>`;}).join(''):'<div class="empty"><h3>Nenhuma venda neste mês</h3><p>As etapas aparecerão aqui quando uma venda for cadastrada.</p></div>'}</div>`;}
function salesCommissionFor(person,entries=monthlySales()){return entries.filter(s=>!s.voided&&(s.originator===person||s.closer===person)).reduce((total,s)=>total+(saleShares(s).find(([id])=>id===person)?.[1]||0),0);}
function compactAllocation(s,person=null){const shares=saleShares(s).filter(([id])=>!person||id===person);if(s.originator===s.closer)return `<small>${esc(salePerson(s.originator))} · trouxe e fechou</small>`;return `<div class="compact-shares">${shares.map(([id,amount])=>`<small><b>${esc(salePerson(id))}</b> · ${money(amount/100)}</small>`).join('')}</div>`;}
function salesRows(entries,person=null){return entries.length?`<div class="sale-table-wrap"><table class="sale-table compact-sales-table"><thead><tr><th>Data / cliente</th><th>Tabela / venda</th><th>Participantes</th><th>${person?'Sua comissão':'Comissão'}</th><th>Ações</th></tr></thead><tbody>${entries.map(s=>`<tr class="${s.voided?'voided':''}"><td>${esc(s.date.split('-').reverse().join('/'))}<strong>${esc(s.client)}</strong>${s.voided?'<small>Cancelada</small>':''}</td><td>${SALE_TABLES[s.table]}<strong>${money(s.amount/100)}</strong>${s.table===0?`<small>${s.installments||1} parcela(s)</small>`:''}</td><td class="sale-participants"><small>Quem trouxe</small><strong>${esc(salePerson(s.originator))}</strong><small>Quem fechou</small><strong>${esc(salePerson(s.closer))}</strong></td><td><strong>${money((person?saleShares(s).find(([id])=>id===person)?.[1]:s.commission)/100)}</strong>${compactAllocation(s,person)}</td><td class="sale-actions">${!s.voided?`<button data-edit-sale="${esc(s.id)}">Editar</button>`:''}<button data-void-sale="${esc(s.id)}">${s.voided?'Restaurar':'Cancelar'}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Nenhuma venda registrada neste mês.</p>';}
function renderSales(){const entries=monthlySales(),active=entries.filter(s=>!s.voided);if(salesPersonFilter&&!state.people.some(p=>p.id===salesPersonFilter))salesPersonFilter='';const shown=salesPersonFilter?entries.filter(s=>s.originator===salesPersonFilter||s.closer===salesPersonFilter):entries,filteredActive=shown.filter(s=>!s.voided),sellerCommission=salesPersonFilter?salesCommissionFor(salesPersonFilter,entries):active.reduce((total,s)=>total+s.commission,0),sellerName=salesPersonFilter?salePerson(salesPersonFilter):'Todos os vendedores';$('#stats').innerHTML=[['Vendas do mês',active.reduce((n,s)=>n+s.amount,0)/100],...SALE_TABLES.map((t,i)=>[t,active.filter(s=>s.table===i).reduce((n,s)=>n+s.amount,0)/100])].map(([t,v])=>`<div class="stat"><span class="stat-label">${t}</span><strong>${money(v)}</strong><small>Volume vendido · cada venda contada uma vez</small></div>`).join('');const tabs=`<nav class="sales-subtabs"><button data-sales-subview="list" class="${salesSubView==='list'?'selected':''}">Vendas do mês</button><button data-sales-subview="pending" class="${salesSubView==='pending'?'selected':''}">Pendências</button></nav>`;const list=`<div class="sales-filter-bar"><label>Filtrar por vendedor<select id="sales-person-filter"><option value="">Todos os vendedores</option>${state.people.map(p=>`<option value="${esc(p.id)}" ${p.id===salesPersonFilter?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div><small>Comissão de ${esc(sellerName)} no mês</small><strong>${money(sellerCommission/100)}</strong><span>${filteredActive.length} venda(s)</span></div></div>${salesRows(shown,salesPersonFilter||null)}`;$('#sales-section').innerHTML=`<div class="section-head"><div><span class="eyebrow">VENDAS DO MÊS</span><h2>Vendas e comissões</h2></div><button class="primary" data-add-sale>＋ Adicionar venda</button></div>${tabs}${salesSubView==='pending'?salesPendingView(active):list}`;}
function personSalesView(){const r=record(),b=r.salesBase||{sales:r.sales,commission:r.commission,excluded:false},hasLegacy=b.commission>0||b.sales.some(n=>n>0);return `<div class="section-head"><h3>Vendas e comissão do mês</h3><button data-main-view="sales">Abrir vendas do mês</button></div><p class="hint">As comissões vêm da lista geral de vendas. O valor da venda abaixo é integral; somente a comissão é dividida entre os participantes.</p>${salesRows(monthlySales().filter(s=>s.originator===selected||s.closer===selected),selected)}${hasLegacy?`<div class="balance-summary"><div>Totais anteriores ${b.excluded?'(fora do cálculo)':'incluídos no cálculo'}<strong>Comissão: ${money(b.commission)}</strong><small>Vendas: ${money(b.sales.reduce((a,n)=>a+n,0))}</small><p class="hint">Valores manuais antigos preservados. Ao cadastrar essas mesmas vendas na lista geral, retire os totais anteriores para não contar duas vezes.</p><button data-toggle-sales-base>${b.excluded?'Reincluir totais anteriores':'Retirar totais anteriores'}</button></div></div>`:''}${commissionPanel()}`;}
function openSale(id=null){saleEditing=id;const s=state.saleEntries.find(s=>s.id===id),f=$('#sale-form');f.reset();$('#sale-title').textContent=s?'Editar venda':'Adicionar venda';const opts='<option value="">Selecione uma pessoa</option>'+state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.role||'PJ')}</option>`).join('');f.elements.originator.innerHTML=opts;f.elements.closer.innerHTML=opts;for(const k of ['client','date','table','originator','closer'])f.elements[k].value=s?s[k]:(k==='date'?$('#month').value+'-01':k==='table'?'0':'');f.elements.amount.value=s?formatCredit(s.amount):'';f.elements.installments.value=s?.installments||1;refreshSaleRates();if(s?.allocations){const first=s.allocations[0],same=s.originator===s.closer;f.elements.originRate.value=first.originRate??(same?first.rate/2:first.rate);f.elements.closerRate.value=first.closerRate??(same?first.rate/2:s.allocations.at(-1).rate);previewSale();}$('#sale-dialog').showModal();}
document.querySelector('#close-sale').onclick=()=>$('#sale-dialog').close();
document.querySelector('#sale-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const credit=parseCredit(f.elements.amount.value),table=Number(f.elements.table.value),installments=table===0?Number(f.elements.installments.value):1;if(!Number.isSafeInteger(credit)||credit<=0||credit>100000000000){toast('Informe um crédito válido, maior que zero e até R$ 1 bilhão.');return;}const entry={id:saleEditing||crypto.randomUUID(),client:f.elements.client.value.trim(),date:f.elements.date.value,table,installments,originator:f.elements.originator.value,closer:f.elements.closer.value,amount:credit,...calculateSale(credit,table,f.elements.originator.value,f.elements.closer.value,Number(f.elements.originRate.value),Number(f.elements.closerRate.value),installments),voided:false};try{validateSales({...state,saleEntries:[entry]});}catch{toast('Confira os dados da venda.');return;}if(!putSale(entry)){toast('Reabra a comissão dos participantes antes de alterar esta venda.');return;}$('#month').value=entry.date.slice(0,7);save();render();$('#sale-dialog').close();toast('Venda salva e comissões atualizadas');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.salesSubview){salesSubView=b.dataset.salesSubview;renderSales();}if(b.dataset.saleStep){const [id,indexText]=b.dataset.saleStep.split(':'),sale=state.saleEntries.find(s=>s.id===id),index=Number(indexText);if(sale&&Number.isInteger(index)&&index>=0&&index<SALE_STEPS.length){const workflow=saleWorkflow(sale);workflow[index]=!workflow[index];sale.workflow=workflow;save();renderSales();toast(workflow[index]?'Etapa concluída':'Etapa reaberta');}}if(b.hasAttribute('data-add-sale'))openSale();if(b.dataset.editSale)openSale(b.dataset.editSale);if(b.dataset.voidSale){const s=state.saleEntries.find(s=>s.id===b.dataset.voidSale),voided=!s.voided,now=new Date(),voidedDate=voided?[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-'):null;if(!putSale({...s,voided,voidedDate})){toast('Estorne o borderô dos participantes antes de alterar esta venda.');return;}save();render();}if(b.hasAttribute('data-toggle-sales-base')){const r=record();if(r.settlement||commissionPayments(r).length){toast('Estorne os pagamentos antes de alterar os totais anteriores.');return;}r.salesBase??={sales:[...r.sales],commission:r.commission,excluded:false};r.salesBase.excluded=!r.salesBase.excluded;syncSales();save();render();}});
document.addEventListener('change',e=>{if(e.target.id==='sales-person-filter'){salesPersonFilter=e.target.value;renderSales();}});

function rateFor(person,table){if(table===0)return 0.8/12;const role=state.people.find(p=>p.id===person)?.commissionRole;return role==='PJ sem garantia'?(table===1?0.8:1):null;}
function calculateSale(amount,table,originator,closer,originRate,closerRate,installments=1){if(table===0)originRate=closerRate=0.8/12;const multiplier=table===0?Math.min(12,Math.max(1,Number.isInteger(installments)?installments:1)):1,same=originator===closer;if(same){const rate=originRate+closerRate,amountDue=Math.round(amount*rate/100*multiplier);return {allocations:[{person:originator,rate,originRate,closerRate,amount:amountDue}],commission:amountDue};}const allocations=[{person:originator,rate:originRate,amount:Math.round(amount*originRate/100*multiplier)},{person:closer,rate:closerRate,amount:Math.round(amount*closerRate/100*multiplier)}];return {allocations,commission:allocations.reduce((n,a)=>n+a.amount,0)};}
function allocationDetail(s,person=null){const installments=s.installments||1;return `<div class="sale-allocations">${saleShares(s).filter(([id])=>!person||id===person).map(([id,amount])=>{const a=s.allocations?.find(a=>a.person===id);return `<div><strong>${esc(salePerson(id))} · ${money(amount/100)}</strong><small>${s.originator===s.closer?'Trouxe e fechou':id===s.originator?'Trouxe o cliente':'Atendeu e fechou'}${a?' · '+(s.amount!==undefined?money(s.amount/100)+' × ':'')+(s.table===0?(s.originator===s.closer?'(0,8% ÷ 12) × 2 × '+installments+' parcela(s)':'(0,8% ÷ 12) × '+installments+' parcela(s)'):(a.rate).toLocaleString('pt-BR',{maximumFractionDigits:6})+'% do crédito'):''}</small></div>`;}).join('')}</div>`;}
function refreshSaleRates(){const f=$('#sale-form'),table=Number(f.elements.table.value),same=f.elements.originator.value===f.elements.closer.value;for(const [field,person] of [['originRate',f.elements.originator.value],['closerRate',f.elements.closer.value]]){const r=rateFor(person,table);f.elements[field].value=r??'';f.elements[field].readOnly=r!==null;f.elements[field].required=true;}f.elements.closerRate.disabled=false;if(same&&f.elements.closerRate.value==='')f.elements.closerRate.value=f.elements.originRate.value;const installmentLabel=f.elements.installments?.closest('label');if(installmentLabel)installmentLabel.hidden=table!==0;if(table!==0)f.elements.installments.value=1;$('#sale-rate-note').textContent=table===0?'Parcelinha: cada participação recebe 0,8% ÷ 12 do crédito por parcela embutida. Se a mesma pessoa trouxe e fechou, recebe as duas participações.':'A taxa informada é aplicada integralmente para quem trouxe e para quem fechou. Se for a mesma pessoa, as duas taxas são somadas.';previewSale();}
function previewSale(){const f=$('#sale-form'),o=f.elements.originator.value,c=f.elements.closer.value,table=Number(f.elements.table.value),installments=table===0?Number(f.elements.installments.value||1):1;const missing=!o||!c||!f.elements.amount.value||f.elements.originRate.value===''||f.elements.closerRate.value==='';$('#sale-preview').innerHTML=missing?'<p class="hint">Preencha o crédito, os participantes e as taxas para visualizar a divisão.</p>':allocationDetail({originator:o,closer:c,table,installments,amount:parseCredit(f.elements.amount.value),...calculateSale(parseCredit(f.elements.amount.value),table,o,c,Number(f.elements.originRate.value),Number(f.elements.closerRate.value),installments)});}
document.querySelector('#sale-form').addEventListener('change',e=>{if(['originator','closer','table'].includes(e.target.name))refreshSaleRates();else previewSale();});
document.querySelector('#sale-form').addEventListener('input',e=>{if(['amount','originRate','closerRate','installments'].includes(e.target.name))previewSale();});
const saleRuleHelp=typeof document.querySelectorAll==='function'?[...document.querySelectorAll('#sale-form .hint')].at(-1):null;if(saleRuleHelp)saleRuleHelp.textContent='Cada taxa é aplicada integralmente. Se a mesma pessoa trouxe e fechou, as duas taxas são somadas. Parcelinha: cada participação usa 0,8% ÷ 12. O cálculo arredonda somente o valor final em centavos.';
const saleForm=document.querySelector('#sale-form');if(saleForm?.elements?.table&&typeof document.createElement==='function'){const label=document.createElement('label');label.innerHTML='Parcelas embutidas (1 a 12)<input name="installments" type="number" min="1" max="12" step="1" value="1" required><small class="hint">Cada parcela adiciona novamente a comissão-base da Parcelinha.</small>';saleForm.elements.table.closest('label')?.after(label);}

function parseCredit(value){const raw=String(value).replace(/R\$/g,'').replace(/\s/g,'');if(!/^(?:\d+|\d{1,3}(?:\.\d{3})+)(?:,\d{0,2})?$/.test(raw))return NaN;const [whole,fraction='']=raw.replace(/\./g,'').split(',');return Number(whole)*100+Number(fraction.padEnd(2,'0'));}
function formatCredit(amount){return (amount/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});}
function maskCredit(input){const raw=input.value,start=input.selectionStart??raw.length,comma=raw.indexOf(','),fraction=comma>=0&&start>comma,digitsBefore=raw.slice(0,start).replace(/\D/g,'').length,amount=parseCredit(raw.replace(/\./g,'').replace(/(,\d{2})\d+$/, '$1'));if(!Number.isSafeInteger(amount)||amount>100000000000000)return;input.value=formatCredit(amount);let caret;if(fraction)caret=input.value.indexOf(',')+1+Math.min(2,start-comma-1);else{let count=0;caret=0;while(caret<input.value.indexOf(',')&&count<digitsBefore){if(/\d/.test(input.value[caret]))count++;caret++;}}input.setSelectionRange(caret,caret);}
